#!/usr/bin/env bash
# The part of the devlink build that runs INSIDE a PS2DEV environment (the
# native toolchain through WSL/Linux/macOS, or the ps2dev/ps2dev image). Both
# build.ps1 and build.sh call this with PS2DEV/PS2SDK/PATH already set and the
# current directory at vendor/tyra/devlink.
#
# Writes:
#   bin/devlink.irx                                   the module
#   ../engine/src/debug/devlink_irx.cpp               the same bytes as a C array
#                                                     (what the engine embeds)
set -euo pipefail

rm -rf .work/iop
mkdir -p .work/iop bin
cp iop/* .work/iop/
( cd .work/iop && make clean >/dev/null 2>&1 || true; make )

cp .work/iop/devlink.irx bin/devlink.irx
chmod 644 bin/devlink.irx

out=../engine/src/debug/devlink_irx.cpp
size=$(wc -c < bin/devlink.irx | tr -d ' ')
{
  echo "// Generated by vendor/tyra/devlink/build.{sh,ps1} from bin/devlink.irx -"
  echo "// do not edit. The IOP side of the devkit channel (docs/devlink.md)."
  echo "//"
  echo "// An ordinary object of libtyra.a: only Tyra::DevLink references it, and"
  echo "// only a debug game's generated devkit code references DevLink, so a"
  echo "// release ELF never pulls these bytes in (the release audit checks)."
  echo "unsigned char devlink_irx[] __attribute__((aligned(16))) = {"
  od -An -v -tx1 bin/devlink.irx | sed -e 's/  */ /g' -e 's/^ //' -e '/^$/d' \
    -e 's/\([0-9a-f][0-9a-f]\)/0x\1,/g'
  echo "};"
  echo "int size_devlink_irx = $size;"
} > "$out"

echo "devlink: bin/devlink.irx ($size bytes) and $out"
